<script setup lang="ts">import {ref} from "vue";import {getFileUrl} from "../types/file.ts";import { convertFileSrc } from "@tauri-apps/api/core";import type {Message} from "../types/message.ts";const props=defineProps<{message:Message;isOwn:boolean;close?:false}>();const emit=defineEmits<{delete:[messageId:number]}>();const isImgOpen=ref(false);function avatarUrl(path: string | null | undefined){if(!path)return "";if(/^(https?:|data:|asset:|blob:)/.test(path))return path;return convertFileSrc(path)}function deleteMessage(){emit("delete",props.message.id)}</script>
<template><article class="message" :class="{'message--own':isOwn,'message--other':!isOwn}"><button v-if="isOwn" class="delete-button" type="button" title="Удалить сообщение" aria-label="Удалить сообщение" @click="deleteMessage">×</button><p v-if="message.type==='text'">{{message.body}}</p><img v-if="message.type==='image'&&message.attachment" class="message-image" :src="getFileUrl(message.attachment)" @click="isImgOpen=true" alt="Изображение"/><div v-if="isImgOpen&&message.attachment" class="modal-overlay" @click.self="isImgOpen=false"><button class="modal-close" type="button" @click="isImgOpen=false">×</button><img class="modal-image" :src="getFileUrl(message.attachment)" alt="Увеличенное изображение"/></div><footer><span class="author"><span class="author-avatar"><img v-if="message.author_avatar" :src="avatarUrl(message.author_avatar)" alt=""/><span v-else>{{message.author_name?.[0]?.toUpperCase()}}</span></span><span>{{message.author_name}}</span></span><span>|</span><span>{{message.created_at}}</span></footer></article></template>
<style scoped>.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.86);display:flex;align-items:center;justify-content:center;z-index:99999;padding:30px}.modal-image{display:block;max-width:90vw;max-height:85vh;object-fit:contain;border-radius:10px}.modal-close{position:fixed;right:20px;top:16px;width:42px;height:42px;border:0;border-radius:50%;background:#fff;color:#111;font-size:28px;cursor:pointer}.message-image{max-width:300px;max-height:300px;border-radius:12px;object-fit:cover;cursor:pointer;display:block}.message{position:relative;max-width:70%;margin:0;padding:10px 12px;border-radius:10px;color:var(--text)}.message--own{align-self:flex-end;background:#386be0;color:#fff}.message--other{align-self:flex-start;background:var(--message-other)}.message p{margin:0;line-height:1.45;overflow-wrap:anywhere}.message footer{display:flex;justify-content:flex-end;gap:5px;margin-top:6px;color:var(--muted);font-size:10px}.message--own footer{color:rgba(255,255,255,.75)}.author{display:inline-flex;align-items:center;gap:4px}.author-avatar{width:18px;height:18px;border-radius:50%;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;background:rgba(0,0,0,.15);font-size:8px;font-weight:700}.author-avatar img{width:100%;height:100%;object-fit:cover;display:block}.delete-button{position:absolute;top:4px;right:5px;width:20px;height:20px;padding:0;border:0;border-radius:50%;background:transparent;color:rgba(255,255,255,.7);font-size:18px;line-height:18px;cursor:pointer;opacity:0;transition:opacity .15s ease,background .15s ease}.message--own:hover .delete-button,.delete-button:focus{opacity:1}.delete-button:hover{background:rgba(0,0,0,.18);color:#fff}</style>
